'use client'

import { useActionState } from 'react'

type ContactState = {
  message: string | null
  error: string | null
}

async function submitContact(prevState: ContactState, formData: FormData): Promise<ContactState> {
  'use server'

  const name = formData.get('name') as string
  const email = formData.get('email') as string
  const message = formData.get('message') as string

  if (!name || name.trim() === '') {
    return { message: null, error: 'Name is required.' }
  }

  if (!email || email.trim() === '') {
    return { message: null, error: 'Email is required.' }
  }

  if (!message || message.trim() === '') {
    return { message: null, error: 'Message is required.' }
  }

  console.log('Contact submitted:', { name, email, message })

  return { message: 'Thank you for your message!', error: null }
}

const initialState: ContactState = { message: null, error: null }

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContact, initialState)

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" placeholder="Your name" />
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" placeholder="Your email" />
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" placeholder="Your message" />
        </div>
        <button type="submit" disabled={isPending}>
          {isPending ? 'Submitting...' : 'Submit'}
        </button>
      </form>
      {state.error && <p style={{ color: 'red' }}>{state.error}</p>}
      {state.message && <p style={{ color: 'green' }}>{state.message}</p>}
    </div>
  )
}

